exemplo:
for i in range(10):
    if i == 3:
        break
    print(i)

class Aluno:
    def __init__(self, nome):
        self.nome = nome

    def falar(self):
        return f"sou {self.nome}"

a = Aluno("Ana")
print(a.falar())
print(a.nome)

for i in range(5):
    if i % 2 == 0:
        continue      # pula os pares
    print(i)

for i, fruta in enumerate(["maçã", "uva"]):
    print(i, fruta)

for i, fruta in enumerate(["maçã", "uva"], start=1):
    print(i, fruta)

for valor in ["10", "abc"]:
    try:
        print(int(valor))
    except ValueError:
        print(f"'{valor}' não é número")

def f():
    try:
        return "do try"
    finally:
        print("finally roda mesmo com return")

print(f())

for fruta in ["maçã", "uva"]:
    print(fruta)

for i in range(3):
    print(i)

nota = 7
if nota >= 9:
    print("excelente")
elif nota >= 6:
    print("aprovado")
else:
    print("reprovado")

def ainda_nao_implementei():
    pass

for i in range(3):
    pass
print("o pass não faz nada, só ocupa o lugar")

def sacar(saldo, valor):
    if valor > saldo:
        raise ValueError("saldo insuficiente")
    return saldo - valor

try:
    sacar(100, 500)
except ValueError as e:
    print("erro:", e)

def dobro(x):
    return x * 2

def nada(x):
    x * 2          # sem return!

print(dobro(5))
print(nada(5))     # None

class Animal:
    def __init__(self, nome):
        self.nome = nome

class Cao(Animal):
    def __init__(self, nome):
        super().__init__(nome)   # chama o pai
        self.som = "au"

c = Cao("Rex")
print(c.nome, c.som)

try:
    n = int("abc")
except ValueError as e:
    print("deu ruim:", e)
finally:
    print("sempre roda")

def contar(n):
    for i in range(n):
        yield i

g = contar(3)
print(list(g))
print(list(g))    # gerador esgotado

aluno = {"nome": "Ana", "nota": 9}
for chave, valor in aluno.items():
    print(chave, "->", valor)

aluno = {"nome": "Ana", "nota": 9}
print(list(aluno.keys()))
print("nome" in aluno)     # não precisa de .keys() aqui

a = {"x": 1}
a.update({"y": 2, "x": 99})   # sobrescreve o x
print(a)

notas = {"ana": 9, "bia": 7}
print(list(notas.values()))
print(sum(notas.values()))
